export function createIndex(){
  let data=[];
  const regions=['North','South','East','West'];
  return{
    async load(count,progress){
      if(!Number.isInteger(count)||count<1)throw Error('Invalid data size');data=[];
      for(let start=0;start<count;start+=1000){
        for(let i=start;i<Math.min(start+1000,count);i++)data.push({id:i+1,customer:`Customer ${i%4096}`,region:regions[i%4],cents:i*7919%1000000,month:i%12+1});
        progress?.(data.length,count);await new Promise(resolve=>setTimeout(resolve,0));
      }
    },
    query({search='',region='',month='',sort='id-asc'}={}){
      const selected=data.filter(row=>(!search||row.customer.includes(search))&&((!region&&!month)||row.region===region||row.month===Number(month)));
      if(sort==='cents-desc')selected.sort((a,b)=>b.cents-a.cents||a.id-b.id);
      else if(sort!=='id-asc')throw Error('Unknown sort');return selected;
    },
  };
}
